effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bool u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
bool u_xlatb4;
vec4 u_xlat5;
vec4 u_xlat6;
int u_xlati6;
vec2 u_xlat7;
ivec2 u_xlati7;
vec4 u_xlat8;
vec2 u_xlat10;
bool u_xlatb10;
float u_xlat11;
vec3 u_xlat14;
vec2 u_xlat15;
bool u_xlatb15;
ivec2 u_xlati16;
bool u_xlatb16;
vec2 u_xlat17;
float u_xlat19;
int u_xlati21;
vec2 u_xlat22;
vec2 u_xlat24;
vec2 u_xlat25;
bool u_xlatb25;
float u_xlat28;
bool u_xlatb28;
float u_xlat29;
int u_xlati30;
float u_xlat32;
float u_xlat33;
int u_xlati33;
float u_xlat34;
void main()
{
    u_xlat0 = vec4(vec4(_spread, _spread, _spread, _spread)) * vec4(13.8461542, 0.0, 32.3076935, 0.0);
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat1 = u_xlat1 * vec4(0.227027029, 0.227027029, 0.227027029, 0.227027029);
    u_xlat2 = u_xlat0.yxwz / _resolution.xyxy;
    u_xlat3 = u_xlat2 + acScreenNorm.xyxy;
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat4 = u_xlat4 * vec4(0.31621623, 0.31621623, 0.31621623, 0.31621623) + u_xlat1;
    u_xlat2 = (-u_xlat2) + acScreenNorm.xyxy;
    u_xlat5 = texture(inputImg, u_xlat2.xy);
    u_xlat4 = u_xlat5 * vec4(0.31621623, 0.31621623, 0.31621623, 0.31621623) + u_xlat4;
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat3 = u_xlat3 * vec4(0.0702702701, 0.0702702701, 0.0702702701, 0.0702702701) + u_xlat4;
    u_xlat2 = texture(inputImg, u_xlat2.zw);
    u_xlat2 = u_xlat2 * vec4(0.0702702701, 0.0702702701, 0.0702702701, 0.0702702701) + u_xlat3;
    u_xlat0 = u_xlat0 / _resolution.xyxy;
    u_xlat3 = u_xlat0 + acScreenNorm.xyxy;
    u_xlat4 = texture(inputImg, u_xlat3.xy);
    u_xlat1 = u_xlat4 * vec4(0.31621623, 0.31621623, 0.31621623, 0.31621623) + u_xlat1;
    u_xlat0 = (-u_xlat0) + acScreenNorm.xyxy;
    u_xlat4 = texture(inputImg, u_xlat0.xy);
    u_xlat1 = u_xlat4 * vec4(0.31621623, 0.31621623, 0.31621623, 0.31621623) + u_xlat1;
    u_xlat3 = texture(inputImg, u_xlat3.zw);
    u_xlat1 = u_xlat3 * vec4(0.0702702701, 0.0702702701, 0.0702702701, 0.0702702701) + u_xlat1;
    u_xlat0 = texture(inputImg, u_xlat0.zw);
    u_xlat0 = u_xlat0 * vec4(0.0702702701, 0.0702702701, 0.0702702701, 0.0702702701) + u_xlat1;
    u_xlat0 = u_xlat0 + u_xlat2;
    u_xlat1.x = (-_decay) + 1.0;
    u_xlat1.x = u_xlat1.x * 0.00999999978 + 0.49000001;
    u_xlatb10 = _fade<0;
    if(u_xlatb10){
        u_xlat10.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
        u_xlat2.xy = vec2(_shape_center.x, _shape_center.y) + vec2(-0.5, -0.5);
        u_xlat10.xy = u_xlat10.xy + (-u_xlat2.xy);
        u_xlat10.xy = u_xlat10.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
        u_xlat28 = _shape_rotation * 0.0174532924;
        u_xlat2.x = sin(u_xlat28);
        u_xlat3.x = cos(u_xlat28);
        u_xlat4.x = sin((-u_xlat28));
        u_xlat4.y = u_xlat3.x;
        u_xlat4.z = u_xlat2.x;
        u_xlat2.x = dot(u_xlat10.xy, u_xlat4.yz);
        u_xlat2.y = dot(u_xlat10.xy, u_xlat4.xy);
        u_xlat10.xy = u_xlat2.xy / vec2(vec2(_shape_scale, _shape_scale));
        u_xlatb28 = _evolution>=(-_evolution);
        u_xlat2.x = fract(abs(_evolution));
        u_xlat28 = (u_xlatb28) ? u_xlat2.x : (-u_xlat2.x);
        u_xlatb2 = u_xlat28<0.0;
        u_xlat11 = u_xlat28 + 1.0;
        u_xlat28 = (u_xlatb2) ? u_xlat11 : u_xlat28;
        u_xlat2.z = 0.0;
        u_xlat29 = 0.0;
        u_xlat3.x = float(0.0);
        u_xlat3.y = float(0.0);
        u_xlat3.z = float(intBitsToFloat(int(0xFFFFFFFFu)));
        u_xlati30 = int(0);
        while(true){
            u_xlatb4 = u_xlati30>=_path_seg_count;
            if(u_xlatb4){break;}
            u_xlat4.xy = (-_path_p0s[u_xlati30].xy) + _path_p0s[u_xlati30].zw;
            u_xlat22.xy = u_xlat4.xy * vec2(3.0, 3.0);
            u_xlat5 = (-_path_p0s[u_xlati30].zxwy) + _path_p1s[u_xlati30].zxwy;
            u_xlat5.xz = u_xlat5.xz * vec2(3.0, 3.0) + (-u_xlat22.xy);
            u_xlat4.xy = (-u_xlat4.xy) * vec2(3.0, 3.0) + u_xlat5.yw;
            u_xlat4.xy = (-u_xlat5.xz) + u_xlat4.xy;
            u_xlat2.xy = u_xlat3.xy;
            u_xlat14.x = u_xlat29;
            u_xlat32 = u_xlat3.z;
            u_xlati6 = 0;
            while(true){
                u_xlatb15 = u_xlati6>=50;
                if(u_xlatb15){break;}
                u_xlat15.x = float(u_xlati6);
                u_xlat15.x = u_xlat15.x * 0.0204081628;
                u_xlat24.x = u_xlat15.x * u_xlat15.x;
                u_xlat33 = u_xlat15.x * u_xlat24.x;
                u_xlat7.xy = u_xlat5.xz * u_xlat24.xx;
                u_xlat24.xy = u_xlat4.xy * vec2(u_xlat33) + u_xlat7.xy;
                u_xlat15.xy = u_xlat22.xy * u_xlat15.xx + u_xlat24.xy;
                u_xlat15.xy = u_xlat15.xy + _path_p0s[u_xlati30].xy;
                if(uint(floatBitsToUint(u_xlat32)) != uint(0)) {
                    u_xlati33 = u_xlati6 + 1;
                    u_xlat32 = 0.0;
                    u_xlat2.xy = u_xlat15.xy;
                    u_xlati6 = u_xlati33;
                    continue;
                }
                u_xlat7.xy = (-u_xlat2.xy) + u_xlat15.xy;
                u_xlat33 = dot(u_xlat7.xy, u_xlat7.xy);
                u_xlat33 = sqrt(u_xlat33);
                u_xlat14.x = u_xlat14.x + u_xlat33;
                u_xlat2.xy = u_xlat15.xy;
                u_xlati6 = u_xlati6 + 1;
                u_xlat32 = 0.0;
            }
            u_xlat29 = u_xlat14.x;
            u_xlati30 = u_xlati30 + 1;
            u_xlat3.xyz = u_xlat2.xyz;
        }
        u_xlat28 = u_xlat28 * u_xlat29;
        u_xlat2.x = float(0.0);
        u_xlat2.y = float(0.0);
        u_xlat2.z = float(0.0);
        u_xlat2.w = float(intBitsToFloat(int(0xFFFFFFFFu)));
        u_xlat3.x = float(0.0);
        u_xlat3.y = float(0.0);
        u_xlati21 = int(0);
        u_xlati30 = int(0);
        while(true){
            u_xlatb4 = u_xlati21>=_path_seg_count;
            u_xlati30 = 0;
            if(u_xlatb4){break;}
            u_xlat4.xy = (-_path_p0s[u_xlati21].xy) + _path_p0s[u_xlati21].zw;
            u_xlat22.xy = u_xlat4.xy * vec2(3.0, 3.0);
            u_xlat5 = (-_path_p0s[u_xlati21].zxwy) + _path_p1s[u_xlati21].zxwy;
            u_xlat5.xz = u_xlat5.xz * vec2(3.0, 3.0) + (-u_xlat22.xy);
            u_xlat4.xy = (-u_xlat4.xy) * vec2(3.0, 3.0) + u_xlat5.yw;
            u_xlat4.xy = (-u_xlat5.xz) + u_xlat4.xy;
            u_xlat14.xz = u_xlat3.xy;
            u_xlat6 = u_xlat2;
            u_xlati7.x = int(0);
            u_xlati16.x = int(0);
            while(true){
                u_xlatb25 = u_xlati7.x>=50;
                u_xlati16.x = 0;
                if(u_xlatb25){break;}
                u_xlat25.x = float(u_xlati7.x);
                u_xlat25.x = u_xlat25.x * 0.0204081628;
                u_xlat34 = u_xlat25.x * u_xlat25.x;
                u_xlat8.x = u_xlat25.x * u_xlat34;
                u_xlat17.xy = u_xlat5.xz * vec2(u_xlat34);
                u_xlat8.xy = u_xlat4.xy * u_xlat8.xx + u_xlat17.xy;
                u_xlat25.xy = u_xlat22.xy * u_xlat25.xx + u_xlat8.xy;
                u_xlat8.yz = u_xlat25.xy + _path_p0s[u_xlati21].xy;
                if(uint(floatBitsToUint(u_xlat6.w)) != uint(0)) {
                    u_xlati16.y = u_xlati7.x + 1;
                    u_xlat8.x = u_xlat6.x;
                    u_xlat6.w = 0.0;
                    u_xlati16.x = 0;
                    u_xlat6.xyz = u_xlat8.xyz;
                    u_xlati7.xy = u_xlati16.yx;
                    continue;
                }
                u_xlat25.xy = (-u_xlat6.yz) + u_xlat8.yz;
                u_xlat25.x = dot(u_xlat25.xy, u_xlat25.xy);
                u_xlat25.x = sqrt(u_xlat25.x);
                u_xlat8.w = u_xlat6.x + u_xlat25.x;
                u_xlatb25 = u_xlat8.w>=u_xlat28;
                if(u_xlatb25){
                    u_xlat6.xyz = u_xlat8.wyz;
                    u_xlat6.w = 0.0;
                    u_xlati16.x = int(0xFFFFFFFFu);
                    u_xlat14.xz = u_xlat8.yz;
                    break;
                }
                u_xlat6.xyz = u_xlat8.wyz;
                u_xlatb16 = u_xlatb25;
                u_xlati7.x = u_xlati7.x + 1;
                u_xlat6.w = 0.0;
            }
            u_xlat2 = u_xlat6;
            u_xlat3.xy = u_xlat14.xz;
            u_xlati30 = u_xlati16.x;
            if(u_xlati16.x != 0) {break;}
            u_xlati21 = u_xlati21 + 1;
            u_xlat3.xy = u_xlat14.xz;
            u_xlati30 = u_xlati16.x;
        }
        u_xlat2.xy = uintBitsToFloat(uvec2(uint(floatBitsToUint(u_xlat3.x)) & uint(u_xlati30), uint(floatBitsToUint(u_xlat3.y)) & uint(u_xlati30)));
        u_xlat10.xy = u_xlat10.xy + (-u_xlat2.xy);
        u_xlat10.x = dot(u_xlat10.xy, u_xlat10.xy);
        u_xlat10.x = sqrt(u_xlat10.x);
        u_xlat19 = _radius * 0.0399999991;
        u_xlat10.x = _radius * 0.100000001 + (-u_xlat10.x);
        u_xlat19 = float(1.0) / u_xlat19;
        u_xlat10.x = u_xlat19 * u_xlat10.x;
        u_xlat10.x = clamp(u_xlat10.x, 0.0, 1.0);
        u_xlat19 = u_xlat10.x * -2.0 + 3.0;
        u_xlat10.x = u_xlat10.x * u_xlat10.x;
        u_xlat10.x = (-u_xlat19) * u_xlat10.x + 1.0;
        u_xlat10.x = u_xlat10.x * 1.60000002;
    } else {
        u_xlat10.x = 0.0;
    }
    fragColor = u_xlat0 * u_xlat1.xxxx + u_xlat10.xxxx;
    return;
}
